rows=[]
refs=[]
for d in range(1,6):
    p=root/f'201912{d:02}_pipeline.csv'
    refs.append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    with p.open(encoding='utf-8-sig',newline='') as f:
        for r in csv.DictReader(f):
            if r['管道划分'] in totals and frozenset((r['起点站名'],r['终点站名'])) in pairs:
                totals[r['管道划分']]+=abs(Decimal(r['管道流量']))
                rows.append({'file':p.name,**r})
