import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190203", "20190204", "20190205", "20190206", "20190207"]

targets = [
    ("永清站", "通州南站", "西气东输二线"),
    ("普光首站", "达州站", "川气东送"),
]

sums = {t: 0.0 for t in targets}
counts = {t: 0 for t in targets}
detail = {t: [] for t in targets}

for d in dates:
    csv_path = DIR / f"{d}_pipeline.csv"
    with open(csv_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            key = (row["起点站名"].strip(), row["终点站名"].strip(), row["管道划分"].strip())
            if key in sums:
                val = abs(float(row["管道流量"]))
                sums[key] += val
                counts[key] += 1
                detail[key].append((d, float(row["管道流量"])))

for t in targets:
    print(t, "days_matched=", counts[t], "daily=", detail[t], "cum_abs=", round(sums[t], 3))

a = sums[targets[0]]
b = sums[targets[1]]
print("diff_abs=", round(abs(a - b), 3))
print("higher=", targets[0] if a > b else targets[1])
